392	// `run --mode hybrid`: orchestrate a QEMU1 fast-forward -> vsim measure+drain
393	// handoff (no QEMU2). The trigger (marker|pc) delimits the ROI; the cycle
394	// figure is the vsim mcycle minus QEMU1's drained mcycle. Replaces the Python
395	// driver's tests/e2e.sh delegation with a single window-cycle line.
396	int run_hybrid(const Cli& cli) {
397	  // Single diagnostic sink for the early-validation returns: prefix + exit 2.
398	  auto fail = [](const std::string& msg) {
399	    std::fprintf(stderr, "andesim run --mode hybrid: %s\n", msg.c_str());
400	    return 2;
401	  };
402	
403	  // --print-memmap: the map describes the run's window (engine + --mem-size),
404	  // not a workload, so the ELF is optional (when given it only adds the
405	  // fit-vs-scratch note) and the trigger machinery is skipped entirely.
406	  const bool memmap_only = cli.print_memmap;
407	  if (!memmap_only) {
408	    if (int rc = check_one_elf(cli, "hybrid")) return rc;
409	  } else if (cli.positional.size() > 1) {
410	    return fail("unexpected argument '" + cli.positional[1] + "'");
411	  }
412	
413	  // Resolve to an absolute, existing ELF through the shared resolver -- the same
414	  // check and "ELF not found" message fast/cycle get (abs_elf already printed on
415	  // failure). pc-trigger resolution below then reads the ELF's .symtab.
416	  std::string elf_path;
417	  if (!cli.positional.empty()) {
418	    elf_path = abs_elf(cli.positional[0], "--mode hybrid");
419	    if (elf_path.empty()) return 2;
420	  }
421	  const fs::path elf{elf_path};  // for .stem() in the banner / PASS lines
422	
423	  // Validate everything cheap BEFORE the expensive engine discovery, so a CLI
424	  // mistake fails fast without spawning a --describe per Verilator build.
425	  std::string err;
426	  Trigger trig;
427	  std::vector<std::string> vsim_extras;
428	  if (!memmap_only) {
429	    trig = hybrid_trigger(cli, elf_path, err);
430	    if (!err.empty()) return fail(err);
431	
432	    // hybrid_trigger has already guaranteed trig.kind is marker|pc (the only
433	    // hybrid triggers; unknown returned an error above) -- exactly the entry
434	    // boundary --verify needs the oracle to arm on.
435	    vsim_extras = vsim_extra_args(cli, trig.kind, err);
436	    if (!err.empty()) return fail(err);
437	  }
438	
439	  // --runtime linux (U9) defaults --mem-size to 1G, same as fast (U2) --
440	  // the app + vlinux's own arenas need more than the plain hybrid default.
441	  long long mem = cli.runtime == "linux" ? 1024LL * 1024 * 1024
442	                                         : 128LL * 1024 * 1024;
443	  if (!cli.mem_size.empty()) {
444	    std::string se;
445	    mem = parse_size(cli.mem_size, se);
446	    if (!se.empty()) return fail("--mem-size: " + se);
447	    // Early cap: QEMU's AE350 DRAM window is 2 GiB and the backend doubles as
448	    // guest RAM here. The physical mmap reserves one V-scratch page above the
449	    // program's RAM (L26/F2), so the usable --mem-size is 2 GiB minus that
450	    // page. Failing now beats allocating a huge mmap file first and letting
451	    // QEMU die late.
452	    if (mem > max_program_mem_bytes())
453	      return fail("--mem-size " + cli.mem_size +
454	                  " exceeds the AE350 DRAM window (2G minus the V-scratch "
455	                  "reservation)");
456	  }
457	
458	  // L26/F3: refuse a run whose static image would extend into the reserved
459	  // V-transport scratch page. Scheme D parks the scratch in the TOP page of the
460	  // physical mmap; a PT_LOAD segment reaching there means the ELF was linked for
461	  // more RAM than --mem-size grants, and QEMU would load it straight onto the
462	  // scratch -> silent corruption. Derive the page's start from
463	  // physical_mmap_bytes (the same sizing the mmap uses) rather than a bare
464	  // `mem`, so the threshold tracks the reservation shape instead of relying on
465	  // the +page/-page adjustments cancelling. ram_base is the fixed andes_ae350
466	  // DRAM base (0; see L10). Skipped when the ELF cannot be read -- downstream
467	  // reports it.
468	  {
469	    std::string e;
470	    const uint64_t top = elf_load_top(elf_path, e);
471	    const uint64_t scratch_gpa =
472	        static_cast<uint64_t>(physical_mmap_bytes(mem)) - HYBRID_V_SCRATCH_BYTES;
473	    if (e.empty() && top > scratch_gpa) {
474	      char msg[256];
475	      std::snprintf(msg, sizeof(msg),
476	                    "ELF static image ends at 0x%llx, overlapping the reserved "
477	                    "V-transport scratch page at 0x%llx (ram_base + --mem-size)"
478	                    "; raise --mem-size or shrink the image",
479	                    static_cast<unsigned long long>(top),
480	                    static_cast<unsigned long long>(scratch_gpa));
481	      return fail(msg);
482	    }
483	  }
484	
485	  // qemu is the built-in fast leg; resolve the accurate (vsim) leg by --engine
486	  // or the sole cycle-accurate engine (reusing the F8 selector).
487	  Discovery disc = discover_engines();
488	  const EngineDescriptor* acc =
489	      resolve_accurate_engine(disc.engines, cli.engine, err);
490	  if (!acc) {
491	    std::fprintf(stderr, "andesim run --mode hybrid: %s\n", err.c_str());
492	    for (const std::string& w : disc.warnings)
493	      std::fprintf(stderr, "andesim: skipped engine: %s\n", w.c_str());
494	    return 2;
495	  }
496	
497	  // ISA sync: both legs must agree on the base ISA width (rv32 engines
498	  // cannot share architectural state with the rv64 fast leg).
499	  if (std::string hw = hybrid_hw_check(*acc); !hw.empty()) return fail(hw);
500	  // ...and the ELF must match that engine width too (same guard as cycle).
501	  if (std::string e = elf_engine_arch_error(elf_path, *acc); !e.empty())
502	    return fail(e);
503	
504	  if (memmap_only) {
505	    // The LM/HVM bases come from the same probe run_plan stages as the fast
506	    // leg's -readconfig, so the printed geometry IS the run's effective one.
507	    // Tolerant like stage_qemu_cfg: a probe failure only drops the LM rows
508	    // (hybrid_memmap warns).
509	    const RunResult probe =
510	        run_process({acc->bin_path, "--print-qemu-config"}, 5000);
511	    const std::string cfg =
512	        (!probe.spawn_failed && !probe.timed_out && probe.rc == 0) ? probe.out
513	                                                                   : "";
514	    std::fprintf(stderr, "[andesim] hybrid memory map: engine=%s mem-size=%s\n",
515	                 acc->id.c_str(),
516	                 fmt_size(static_cast<uint64_t>(mem)).c_str());
517	    std::fputs(render_memmap(hybrid_memmap(*acc, mem, cfg)).c_str(), stdout);
518	    // With an ELF given, say where its static image lands in that window.
519	    if (!elf_path.empty()) {
520	      std::string e;
521	      const uint64_t top = elf_load_top(elf_path, e);
522	      if (e.empty())
523	        std::printf("ELF %s: static image top 0x%llx (%s)\n",
524	                    elf.stem().string().c_str(),
525	                    static_cast<unsigned long long>(top),
526	                    top <= static_cast<uint64_t>(mem)
527	                        ? "fits DRAM"
528	                        : "OVERLAPS the reserved V-scratch page; raise "
529	                          "--mem-size");
530	    }
531	    return 0;
532	  }
533	
534	  // --runtime linux (U9): stage a manifested vlinux.elf that boots the app
535	  // under the proxy kernel, same as run_fast -- but here BOTH legs share
536	  // plan.elf (Plan's own contract: "the ELF every leg launches"), so
537	  // staging once and pointing plan.elf at the result covers the fast-
538	  // forward QEMU leg AND the vsim accurate leg with no per-leg special
539	  // casing. PC-mode triggers already resolved --pc-start/--pc-end against
540	  // elf_path (the app's own ELF, correctly) BEFORE this point -- vlinux's
541	  // own symbol table would have been the wrong one for that lookup.
542	  std::string boot_elf = elf_path;
543	  if (cli.runtime == "linux") {
544	    std::string stage_err;
545	    boot_elf = stage_linux_runtime(elf_path, static_cast<uint64_t>(mem),
546	                                   cli.passthrough, stage_err);
547	    if (boot_elf.empty()) return fail(stage_err);
548	    log_line(kLogInfo, "[andesim] --runtime linux: staged %s (app=%s)",
549	             boot_elf.c_str(), elf_path.c_str());

