29	// Human-readable byte count: "8.0 GiB", "512.0 MiB", "1024 B" (one decimal,
30	// TiB/GiB/MiB/KiB, else "N B").
31	std::string format_bytes(long long n) {
32	  struct Unit {
33	    const char* suffix;
34	    long long mul;
35	  };
36	  static const Unit units[] = {
37	      {"TiB", 1024LL * 1024 * 1024 * 1024},
38	      {"GiB", 1024LL * 1024 * 1024},
39	      {"MiB", 1024LL * 1024},
40	      {"KiB", 1024LL},
41	  };
42	  for (const Unit& u : units) {
43	    if (n >= u.mul) {
44	      char buf[64];
45	      std::snprintf(buf, sizeof(buf), "%.1f %s",
46	                    static_cast<double>(n) / static_cast<double>(u.mul),
47	                    u.suffix);
48	      return buf;
49	    }
50	  }
51	  return std::to_string(n) + " B";
52	}
