91	long long max_program_mem_bytes() {
92	  // AE350 DRAM window is 2 GiB; leave room for the scratch page on top.
93	  constexpr long long kAe350DramWindowBytes = 2LL * 1024 * 1024 * 1024;
94	  return kAe350DramWindowBytes - HYBRID_V_SCRATCH_BYTES;
95	}
